import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { extractFileMeta, isComponentFile } from "../scanner";
import type { RouteMeta } from "../guard/types";

const MIDDLEWARE_NAMES = ["_middleware", "middleware"];
const LAYOUT_NAMES = ["_layout", "layout"];
const EXTENSIONS = [".tsx", ".ts", ".jsx", ".js", ".json"];

/**
 * Finds the nearest ancestor middleware file for a given relative route file.
 */
export function findAncestorMiddleware(file: string, baseDir: string): { relativePath?: string; fullPath?: string } {
    if (!baseDir) return {};

    const dir = dirname(file).replace(/\\/g, "/");
    const segments = dir === "." ? [] : dir.split("/").filter(Boolean);

    for (let i = segments.length; i >= 0; i--) {
        const currentDir = segments.slice(0, i).join("/");
        for (const name of MIDDLEWARE_NAMES) {
            for (const ext of EXTENSIONS) {
                const candidateRel = currentDir ? `${currentDir}/${name}${ext}` : `${name}${ext}`;
                const candidateFull = join(baseDir, candidateRel);
                if (existsSync(candidateFull)) {
                    return { relativePath: candidateRel, fullPath: candidateFull };
                }
            }
        }
    }

    return {};
}

/**
 * Finds cascading layout files from root down to the target directory.
 */
export function findCascadingLayouts(file: string, baseDir: string): string[] {
    if (!baseDir) return [];

    const dir = dirname(file).replace(/\\/g, "/");
    const segments = dir === "." ? [] : dir.split("/").filter(Boolean);
    const layouts: string[] = [];

    for (let i = 0; i <= segments.length; i++) {
        const currentDir = segments.slice(0, i).join("/");
        for (const name of LAYOUT_NAMES) {
            for (const ext of EXTENSIONS) {
                const candidateRel = currentDir ? `${currentDir}/${name}${ext}` : `${name}${ext}`;
                const candidateFull = join(baseDir, candidateRel);
                if (existsSync(candidateFull) && !layouts.includes(candidateRel)) {
                    layouts.push(candidateRel);
                }
            }
        }
    }

    return layouts;
}

/**
 * Resolves combined metadata for a route file:
 * merges nearest ancestor middleware meta with in-page meta.
 */
export function resolveCombinedMeta(
    file: string,
    baseDir: string
): {
    meta?: RouteMeta;
    groupMeta?: RouteMeta;
    groupName?: string;
    middlewareFile?: string;
    middlewareComponent?: string;
    layoutFiles?: string[];
} {
    if (!baseDir) return {};

    const fullPagePath = join(baseDir, file);
    const pageMeta = extractFileMeta(fullPagePath);

    const { relativePath: middlewareFile, fullPath: fullMiddlewarePath } = findAncestorMiddleware(file, baseDir);
    const middlewareMeta = fullMiddlewarePath ? extractFileMeta(fullMiddlewarePath) : undefined;
    const isComp = fullMiddlewarePath ? isComponentFile(fullMiddlewarePath) : false;
    const middlewareComponent = isComp ? middlewareFile : undefined;
    const groupMeta = !isComp && middlewareMeta ? middlewareMeta : undefined;
    const rawGroupName = middlewareFile ? dirname(middlewareFile).replace(/\\/g, "/") : undefined;
    const groupName = rawGroupName && rawGroupName !== "." ? rawGroupName : undefined;

    const layoutFiles = findCascadingLayouts(file, baseDir);

    let combinedMeta: RouteMeta | undefined;
    if (middlewareMeta || pageMeta) {
        combinedMeta = {
            ...(middlewareMeta || {}),
            ...(pageMeta || {})
        };
    }

    return {
        meta: combinedMeta && Object.keys(combinedMeta).length > 0 ? combinedMeta : undefined,
        groupMeta,
        groupName,
        middlewareFile,
        middlewareComponent,
        layoutFiles: layoutFiles.length > 0 ? layoutFiles : undefined
    };
}
