import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { RouterWriter, WriterOptions } from "./types";
import { normalizeImportPath, toRoutePath } from "../resolver";
import type { RouteItem } from "../generator";

function toPascalCase(str: string): string {
    return str
        .replace(/[^a-zA-Z0-9]/g, " ")
        .split(/\s+/)
        .filter(Boolean)
        .map(w => w.charAt(0).toUpperCase() + w.slice(1))
        .join("");
}

function getUniqueName(baseName: string, used: Set<string>): string {
    let name = baseName;
    let counter = 2;
    while (used.has(name)) {
        name = `${baseName}_${counter++}`;
    }
    used.add(name);
    return name;
}

function toRouteComponentName(file: string, used: Set<string>): string {
    const clean = file.replace(/\.[^/.]+$/, "");
    if (clean === "404" || clean === "_404") {
        return getUniqueName("NotFoundRoute", used);
    }
    if (clean === "[...slug]" || clean.endsWith("/[...slug]")) {
        const prefix = clean.replace(/\/\[\.\.\.slug\]$/, "");
        const prefixName = prefix ? toPascalCase(prefix) : "";
        return getUniqueName(`${prefixName}CatchAllRoute`, used);
    }

    const parts = clean.split("/").map(toPascalCase).filter(Boolean);
    const dedupled: string[] = [];
    for (const part of parts) {
        if (dedupled.length === 0 || dedupled[dedupled.length - 1] !== part) {
            dedupled.push(part);
        }
    }

    const base = dedupled.join("") || "Index";
    return getUniqueName(`${base}Route`, used);
}

function toMiddlewareComponentName(file: string, used: Set<string>): string {
    const dir = file.replace(/\/[^/]+$/, "").replace(/\.[^/.]+$/, "");
    const base = toPascalCase(dir) || "Root";
    return getUniqueName(`${base}Middleware`, used);
}

function toGroupGuardName(groupName: string, used: Set<string>): string {
    const base = toPascalCase(groupName) || "Root";
    return getUniqueName(`${base}GroupGuard`, used);
}

function formatMeta(meta: Record<string, unknown>, indent = 4): string {
    const json = JSON.stringify(meta, null, 2);
    const unquotedKeys = json.replace(/"([a-zA-Z_$][a-zA-Z0-9_$]*)":/g, "$1:");
    const pad = " ".repeat(indent);
    return unquotedKeys
        .split("\n")
        .map((line, idx) => (idx === 0 ? line : `${pad}${line}`))
        .join("\n");
}

export function reactRouterWriter(): RouterWriter {
    return {
        write(routes: RouteItem[], options: WriterOptions) {
            const { outputDir, fileName, importBase, pagesDir } = options;

            mkdirSync(outputDir, { recursive: true });

            const usedNames = new Set<string>();

            // 1. Assign semantic component names for each route
            const routeVarNames: string[] = routes.map(r =>
                toRouteComponentName(r.file, usedNames)
            );

            // 2. Identify and assign names for Component Middlewares (e.g. _middleware.tsx)
            const middlewareCompMap = new Map<string, string>();
            routes.forEach(r => {
                if (r.middlewareComponent && !middlewareCompMap.has(r.middlewareComponent)) {
                    middlewareCompMap.set(
                        r.middlewareComponent,
                        toMiddlewareComponentName(r.middlewareComponent, usedNames)
                    );
                }
            });

            // 3. Identify and assign names for Inlined Config Group Guards (e.g. _middleware.ts exporting object)
            const groupGuardMap = new Map<string, { guardName: string; meta: Record<string, unknown> }>();
            routes.forEach(r => {
                if (!r.middlewareComponent && r.groupMeta && r.groupName && !groupGuardMap.has(r.groupName)) {
                    groupGuardMap.set(r.groupName, {
                        guardName: toGroupGuardName(r.groupName, usedNames),
                        meta: r.groupMeta as Record<string, unknown>
                    });
                }
            });

            // 4. Generate imports for route components (Clean static imports without /* @vite-ignore */)
            const routeDeclarations = routes.map((r, idx) => {
                const varName = routeVarNames[idx];
                const importPath = `${importBase}/${normalizeImportPath(r.file)}`;
                return `const ${varName} = lazy(() => import("${importPath}"));`;
            });

            // 5. Generate imports for component middlewares (without /* @vite-ignore */)
            const middlewareCompDeclarations = Array.from(middlewareCompMap.entries()).map(([file, varName]) => {
                const importPath = `${importBase}/${normalizeImportPath(file)}`;
                return `const ${varName} = lazy(() => import("${importPath}"));`;
            });

            // 6. Generate inlined Group Guard components for metadata objects (Zero waterfall, zero crash)
            const groupGuardDeclarations = Array.from(groupGuardMap.values()).map(({ guardName, meta }) => {
                return [
                    `const ${guardName} = ({ auth }: { auth?: AuthState }) => (`,
                    `  <RouteGuard meta={${formatMeta(meta, 4)}} auth={auth}>`,
                    `    <Outlet />`,
                    `  </RouteGuard>`,
                    `);`
                ].join("\n");
            });

            // 7. Generate routerConfig array entries with trailing commas
            const generateRouteBlock = (r: RouteItem, idx: number) => {
                const pathVal = r.path || toRoutePath(r.file, pagesDir);
                const varName = routeVarNames[idx];
                const lines = [
                    `  {`,
                    `    path: "${pathVal}",`,
                    `    component: ${varName},`
                ];

                if (r.meta && Object.keys(r.meta).length > 0) {
                    lines.push(`    meta: ${formatMeta(r.meta, 4)},`);
                }

                lines.push(`  }`);
                return lines.join("\n");
            };

            // 8. Group routes for JSX element hierarchy
            type RouteEntry = { route: RouteItem; varName: string };
            const compGrouped = new Map<string, RouteEntry[]>();
            const metaGrouped = new Map<string, RouteEntry[]>();
            const topLevel: RouteEntry[] = [];

            routes.forEach((r, idx) => {
                const entry = { route: r, varName: routeVarNames[idx] };
                if (r.middlewareComponent && middlewareCompMap.has(r.middlewareComponent)) {
                    const key = r.middlewareComponent;
                    if (!compGrouped.has(key)) compGrouped.set(key, []);
                    compGrouped.get(key)!.push(entry);
                } else if (!r.middlewareComponent && r.groupName && groupGuardMap.has(r.groupName)) {
                    const key = r.groupName;
                    if (!metaGrouped.has(key)) metaGrouped.set(key, []);
                    metaGrouped.get(key)!.push(entry);
                } else {
                    topLevel.push(entry);
                }
            });

            const renderElementCall = (varName: string, r: RouteItem) => {
                const pathVal = r.path || toRoutePath(r.file, pagesDir);
                const metaArg = r.meta && Object.keys(r.meta).length > 0 ? formatMeta(r.meta, 12) : "undefined";
                return `renderRouteElement(${varName}, ${metaArg}, "${pathVal}", props)`;
            };

            const jsxElements: string[] = [];

            // Add top-level routes
            topLevel.forEach(({ route, varName }) => {
                const pathVal = route.path || toRoutePath(route.file, pagesDir);
                jsxElements.push(
                    `      <Route key="${pathVal}" path="${pathVal}" element={${renderElementCall(varName, route)}} />`
                );
            });

            // Add routes wrapped by Inlined Config Group Guards (zero waterfall)
            metaGrouped.forEach((groupEntries, groupName) => {
                const { guardName } = groupGuardMap.get(groupName)!;
                jsxElements.push(`      <Route element={<${guardName} auth={props?.auth} />}>`);
                groupEntries.forEach(({ route, varName }) => {
                    const pathVal = route.path || toRoutePath(route.file, pagesDir);
                    jsxElements.push(
                        `        <Route key="${pathVal}" path="${pathVal}" element={${renderElementCall(varName, route)}} />`
                    );
                });
                jsxElements.push(`      </Route>`);
            });

            // Add routes wrapped by Component Middleware (e.g. _middleware.tsx)
            compGrouped.forEach((groupEntries, middlewareFile) => {
                const varName = middlewareCompMap.get(middlewareFile)!;
                jsxElements.push(`      <Route element={<${varName} />}>`);
                groupEntries.forEach(({ route, varName: compVarName }) => {
                    const pathVal = route.path || toRoutePath(route.file, pagesDir);
                    jsxElements.push(
                        `        <Route key="${pathVal}" path="${pathVal}" element={${renderElementCall(compVarName, route)}} />`
                    );
                });
                jsxElements.push(`      </Route>`);
            });

            // 9. Assemble full router file
            const hasOutlet = groupGuardDeclarations.length > 0;
            const routerImports = hasOutlet
                ? 'import { Route, Outlet } from "react-router-dom";'
                : 'import { Route } from "react-router-dom";';

            const content = [
                "// This file is auto-generated by @zarr20/rakit-routes",
                "// Do not edit this file manually",
                "",
                'import { lazy, type ComponentType, type ReactNode } from "react";',
                routerImports,
                'import { RouteGuard, type AuthState } from "@zarr20/rakit-routes/client";',
                "",
                "// Route Components",
                routeDeclarations.join("\n"),
                "",
                ...(middlewareCompDeclarations.length > 0
                    ? ["// Middleware Layout Components", middlewareCompDeclarations.join("\n"), ""]
                    : []),
                ...(groupGuardDeclarations.length > 0
                    ? ["// Group Route Guards", groupGuardDeclarations.join("\n\n"), ""]
                    : []),
                "export interface GeneratedRoutesProps {",
                "  auth?: AuthState;",
                "  wrapper?: ComponentType<{",
                "    component: ComponentType<any>;",
                "    meta?: Record<string, unknown>;",
                "    path: string;",
                "  }>;",
                "}",
                "",
                "function renderRouteElement(",
                "  Component: ComponentType<any>,",
                "  meta?: Record<string, unknown>,",
                "  path?: string,",
                "  props?: GeneratedRoutesProps",
                "): ReactNode {",
                "  if (props?.wrapper) {",
                "    const Wrapper = props.wrapper;",
                '    return <Wrapper component={Component} meta={meta} path={path || ""} />;',
                "  }",
                "  if (props?.auth && meta) {",
                "    return (",
                "      <RouteGuard meta={meta} auth={props.auth}>",
                "        <Component />",
                "      </RouteGuard>",
                "    );",
                "  }",
                "  return <Component />;",
                "}",
                "",
                "export function generatedRoutes(props?: GeneratedRoutesProps): ReactNode {",
                "  return (",
                "    <>",
                jsxElements.join("\n"),
                "    </>",
                "  );",
                "}",
                "",
                "export function GeneratedRoutes(props: GeneratedRoutesProps = {}): ReactNode {",
                "  return generatedRoutes(props);",
                "}",
                "",
                "const router = [",
                routes.map(generateRouteBlock).join(",\n"),
                "];",
                "",
                "export { router, router as routes, router as routerConfig };",
                "export default router;",
                ""
            ].join("\n");

            const filePath = join(outputDir, `${fileName}.tsx`);

            writeFileSync(filePath, content, { encoding: "utf-8" });

            console.log(`✔ Router file generated at: ${filePath}`);
        }
    };
}
