import { existsSync, readFileSync } from "node:fs";
import { extname } from "node:path";
import type { RouteMeta } from "../guard/types";

/**
 * Safely extracts RouteMeta from an object literal substring.
 */
function parseObjectLiteral(raw: string): RouteMeta {
    const meta: RouteMeta = {};

    // 1. Parse string arrays (roles, permissions)
    const arrayRegex = /([a-zA-Z_$][a-zA-Z0-9_$]*)\s*:\s*\[([\s\S]*?)\]/g;
    let arrayMatch: RegExpExecArray | null;
    while ((arrayMatch = arrayRegex.exec(raw)) !== null) {
        const key = arrayMatch[1];
        const itemsContent = arrayMatch[2];
        const items = itemsContent
            .split(",")
            .map(s => s.trim().replace(/^['"`]|['"`]$/g, ""))
            .filter(Boolean);

        if (key === "roles") meta.roles = items;
        else if (key === "permissions") meta.permissions = items;
        else meta[key] = items;
    }

    // 2. Parse booleans
    const boolRegex = /([a-zA-Z_$][a-zA-Z0-9_$]*)\s*:\s*(true|false)/g;
    let boolMatch: RegExpExecArray | null;
    while ((boolMatch = boolRegex.exec(raw)) !== null) {
        const key = boolMatch[1];
        const val = boolMatch[2] === "true";
        if (key === "protected") meta.protected = val;
        else if (key === "guestOnly") meta.guestOnly = val;
        else meta[key] = val;
    }

    // 3. Parse string values
    const stringRegex = /([a-zA-Z_$][a-zA-Z0-9_$]*)\s*:\s*(?:['"`](.*?)['"`])/g;
    let strMatch: RegExpExecArray | null;
    while ((strMatch = stringRegex.exec(raw)) !== null) {
        const key = strMatch[1];
        const val = strMatch[2];
        if (key === "title") meta.title = val;
        else if (key === "redirect") meta.redirect = val;
        else if (key === "layout") meta.layout = val;
        else if (!meta[key]) meta[key] = val;
    }

    return meta;
}

/**
 * Extracts a balanced object literal `{ ... }` following a matched export keyword.
 */
function extractBalancedBlock(content: string, searchRegex: RegExp): string | null {
    const match = searchRegex.exec(content);
    if (!match) return null;

    const startMatchIndex = match.index + match[0].length - 1; // points to the '{'
    let depth = 0;
    let inSingleQuote = false;
    let inDoubleQuote = false;
    let inBacktick = false;
    let inLineComment = false;
    let inBlockComment = false;
    let startIndex = -1;

    for (let i = startMatchIndex; i < content.length; i++) {
        const char = content[i];
        const nextChar = content[i + 1];

        if (inLineComment) {
            if (char === "\n") inLineComment = false;
            continue;
        }
        if (inBlockComment) {
            if (char === "*" && nextChar === "/") {
                inBlockComment = false;
                i++;
            }
            continue;
        }
        if (inSingleQuote) {
            if (char === "\\") { i++; continue; }
            if (char === "'") inSingleQuote = false;
            continue;
        }
        if (inDoubleQuote) {
            if (char === "\\") { i++; continue; }
            if (char === '"') inDoubleQuote = false;
            continue;
        }
        if (inBacktick) {
            if (char === "\\") { i++; continue; }
            if (char === "`") inBacktick = false;
            continue;
        }

        if (char === "/" && nextChar === "/") {
            inLineComment = true;
            i++;
            continue;
        }
        if (char === "/" && nextChar === "*") {
            inBlockComment = true;
            i++;
            continue;
        }

        if (char === "'") { inSingleQuote = true; continue; }
        if (char === '"') { inDoubleQuote = true; continue; }
        if (char === "`") { inBacktick = true; continue; }

        if (char === "{") {
            if (depth === 0) startIndex = i;
            depth++;
        } else if (char === "}") {
            depth--;
            if (depth === 0 && startIndex !== -1) {
                return content.slice(startIndex, i + 1);
            }
        }
    }

    return null;
}

/**
 * Statically extracts RouteMeta from a file path without executing it.
 */
export function extractFileMeta(filePath: string): RouteMeta | undefined {
    if (!existsSync(filePath)) return undefined;

    const ext = extname(filePath);
    if (ext === ".json") {
        try {
            return JSON.parse(readFileSync(filePath, "utf-8")) as RouteMeta;
        } catch {
            return undefined;
        }
    }

    const content = readFileSync(filePath, "utf-8");

    // Look for named export: export const meta = { ... } or export const routeMeta = { ... }
    const namedExportRegex = /export\s+(?:const|let|var)\s+(?:meta|routeMeta|middleware)\s*(?::\s*[^=]+)?=\s*\{/;
    const namedBlock = extractBalancedBlock(content, namedExportRegex);
    if (namedBlock) {
        return parseObjectLiteral(namedBlock);
    }

    // Look for default export: export default { ... }
    const defaultExportRegex = /export\s+default\s*\{/;
    const defaultBlock = extractBalancedBlock(content, defaultExportRegex);
    if (defaultBlock) {
        return parseObjectLiteral(defaultBlock);
    }

    return undefined;
}
