import { resolveRoutePath } from "../resolver";
import { RouteItem } from "./types";
import { sortRoutes } from "./routeSorter";
import { resolveCombinedMeta } from "./metadataResolver";

/**
 * Generates an array of sorted, resolved route items from a list of scanned page files,
 * automatically resolving in-page metadata and cascading middleware/layout files.
 */
export function generateRouter(files: string[], baseDir = ""): RouteItem[] {
    const rawRoutes: RouteItem[] = files.map(file => {
        const path = resolveRoutePath(file, baseDir);
        const { meta, groupMeta, groupName, middlewareFile, middlewareComponent, layoutFiles } = baseDir
            ? resolveCombinedMeta(file, baseDir)
            : {};

        return {
            path,
            file,
            ...(meta ? { meta } : {}),
            ...(groupMeta ? { groupMeta } : {}),
            ...(groupName ? { groupName } : {}),
            ...(middlewareFile ? { middlewareFile } : {}),
            ...(middlewareComponent ? { middlewareComponent } : {}),
            ...(layoutFiles ? { layoutFiles } : {})
        };
    });

    return sortRoutes(rawRoutes);
}
